$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'scripts\collect-repair-proof.ps1';$out=Join-Path $env:TEMP 'beadwise-repair-proof.json'
try{& $script -OutputPath $out;$r=Get-Content -Raw $out|ConvertFrom-Json;foreach($id in 'C-REPAIR-006','C-REPAIR-008','C-REPAIR-009','C-REPAIR-010'){if($id -notin @($r.probes.featureId)){throw "missing $id"}};if($r.commandsExecuted.Count){throw 'repair command was executed'};'PASS: repair dispatch/history/source/readiness gates ran without repair'}finally{Remove-Item $out -Force -ErrorAction SilentlyContinue}
